@DisplayName("재고가 부족하면 예외가 난다")
@Test
void createOrderWithNotEnoughStock() {
    // given
    Product product1 = Product.builder()
            .productNumber("001").type(BOTTLE).sellingStatus(SELLING)
            .name("아메리카노").price(4000).build();
    Product product2 = Product.builder()
            .productNumber("002").type(BOTTLE).sellingStatus(SELLING)
            .name("카페라떼").price(4500).build();
    productRepository.saveAll(List.of(product1, product2));

    Stock stock1 = Stock.builder().productNumber("001").quantity(2).build();
    Stock stock2 = Stock.builder().productNumber("002").quantity(0).build();
    stockRepository.saveAll(List.of(stock1, stock2));

    OrderCreateRequest request = OrderCreateRequest.builder()
            .productNumbers(List.of("001", "002")).build();

    // when & then
    assertThatThrownBy(() -> orderService.createOrder(request, 영업중))
            .hasMessage("재고가 부족한 상품이 있습니다.");
}

